-- Part of Fantasy Glass UI, kept in a third folder that the game loads only for players who use
-- the add-on in a language other than English. The main add-on shares its table as the global
-- FantasyGlassUI; the translations hang off that.
local ns = _G.FantasyGlassUI
if type(ns) ~= "table" or type(ns.locales) ~= "table" then return end

-- Translations for Fantasy Glass UI.
--
-- German, French and Spanish are included below. They cover the labels you see most: the options,
-- the setup, panel names and the commonest messages. Longer explanations (tooltips, the setup's
-- paragraphs, most chat lines) are not translated yet and show in English. These translations have
-- not been checked by native speakers; corrections are welcome.
--
-- How to add or improve a language:
--   1. In the game, type  /fgui strings  to get every label the add-on has shown so far, already laid
--      out as a table like the ones below. (Open the options tabs first so their labels are included.)
--   2. Paste it here, change "xxXX" to your language code (deDE, frFR, esES, ruRU, koKR, zhCN ...),
--      and fill in the right-hand side of each line. Lines you leave empty stay in English.
--   3. Chat messages are in the list too. Keep any %s or %d in them: that is where a value goes.


-- German ---------------------------------------------------------------------------------------------
